const kv = await Deno.openKv();

export enum GitChangelogManagerInputAction {
  READ = "read",
  APPEND = "append",
  WRITE = "write",
}

export enum GitChangelogManagerOutputStatus {
  SUCCESS = "success",
  ERROR = "error",
}

export interface IGitChangelogManagerInput {
  /** The text to write or append into the changelog. Required if `action` is `append` or `write`. */
  text?: string;
  /** The action to perform. */
  action: GitChangelogManagerInputAction;
}

export interface IGitChangelogManagerOutput {
  /** The changelog content. */
  text?: string;
  /** The status of the execution. */
  status: GitChangelogManagerOutputStatus;
}

export async function toolHandler(args: IGitChangelogManagerInput): Promise<IGitChangelogManagerOutput> {
  const { action, text } = args;

  try {
    const currentBranchName = await getCurrentBranchName();
    const changelogKey = buildChangelogKey(currentBranchName);
    const isReadAction = action === GitChangelogManagerInputAction.READ;
    const isAppendAction = action === GitChangelogManagerInputAction.APPEND;
    const isWriteAction = action === GitChangelogManagerInputAction.WRITE;

    switch (true) {
      case isReadAction: {
        const changelogText = await readChangelog(changelogKey);
        const output = buildSuccessOutput(changelogText);

        return output;
      }
      case isAppendAction: {
        const ensuredText = ensureText(text, action);
        const currentChangelog = await readChangelog(changelogKey);
        const updatedChangelog = appendChangelog(currentChangelog, ensuredText);

        await kv.set(changelogKey, updatedChangelog);

        const output = buildSuccessOutput(updatedChangelog);

        return output;
      }
      case isWriteAction: {
        const ensuredText = ensureText(text, action);

        await kv.set(changelogKey, ensuredText);

        const output = buildSuccessOutput(ensuredText);

        return output;
      }
      default: {
        throw new Error("Unsupported changelog action.");
      }
    }
  } catch (error) {
    const errorMessage = getErrorMessage(error);
    const output = buildErrorOutput(errorMessage);

    return output;
  }
}

async function getCurrentBranchName() {
  const command = new Deno.Command("git", {
    args: ["rev-parse", "--abbrev-ref", "HEAD"],
    cwd: Deno.cwd(),
    stdout: "piped",
    stderr: "piped",
  });
  const { code, stdout, stderr } = await command.output();
  const stdoutText = new TextDecoder().decode(stdout).trim();
  const stderrText = new TextDecoder().decode(stderr).trim();
  const hasFailed = code !== 0;

  if (hasFailed) {
    const errorSuffix = buildGitErrorSuffix(stdoutText, stderrText);
    const errorMessage = `Failed to read git branch.${errorSuffix}`;

    throw new Error(errorMessage);
  }

  const isBranchNameMissing = stdoutText.length === 0;

  if (isBranchNameMissing) {
    throw new Error("Git branch name is empty.");
  }

  return stdoutText;
}

function buildGitErrorSuffix(stdoutText: string, stderrText: string) {
  const isStderrEmpty = stderrText.length === 0;
  const isStdoutEmpty = stdoutText.length === 0;
  const shouldReturnEmptySuffix = isStderrEmpty && isStdoutEmpty;

  if (shouldReturnEmptySuffix) {
    return "";
  }

  const errorSuffix = isStderrEmpty ? ` ${stdoutText}` : ` ${stderrText}`;

  return errorSuffix;
}

function buildChangelogKey(branchName: string) {
  const key = ["git-changelog", branchName];

  return key;
}

async function readChangelog(changelogKey: Deno.KvKey) {
  const changelogEntry = await kv.get<string>(changelogKey);
  const changelogText = changelogEntry.value ?? "";

  return changelogText;
}

function ensureText(text: string | undefined, action: GitChangelogManagerInputAction) {
  const isTextMissing = text === undefined;

  if (isTextMissing) {
    throw new Error(`Missing 'text' for '${action}' action.`);
  }

  return text;
}

function appendChangelog(currentChangelog: string, newEntry: string) {
  const isCurrentEmpty = currentChangelog.length === 0;
  const separator = isCurrentEmpty ? "" : "\n";
  const updatedChangelog = `${currentChangelog}${separator}${newEntry}`;

  return updatedChangelog;
}

function buildSuccessOutput(text: string): IGitChangelogManagerOutput {
  const output = {
    text,
    status: GitChangelogManagerOutputStatus.SUCCESS,
  };

  return output;
}

function buildErrorOutput(text: string): IGitChangelogManagerOutput {
  const output = {
    text,
    status: GitChangelogManagerOutputStatus.ERROR,
  };

  return output;
}

function getErrorMessage(error: unknown) {
  const isErrorInstance = error instanceof Error;

  if (isErrorInstance) {
    return error.message;
  }

  return "Unknown error.";
}
